dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ Сотрудники.Ссылка КАК Сотрудник, &Период КАК Период ПОМЕСТИТЬ ВТСотрудники {ВЫБРАТЬ Сотрудник.*} ИЗ Справочник.Сотрудники КАК Сотрудники {ГДЕ Сотрудники.Ссылка.* КАК Сотрудник, Сотрудники.Код КАК ТабельныйНомер, Сотрудники.ФизическоеЛицо.*, Сотрудники.ГоловнаяОрганизация.*, Сотрудники.ФизическоеЛицо.Пол КАК Пол, Сотрудники.ФизическоеЛицо.ДатаРождения КАК ДатаРождения, Сотрудники.ФизическоеЛицо.ИНН КАК ИНН, Сотрудники.ФизическоеЛицо.СтраховойНомерПФР КАК СтраховойНомерПФР, Сотрудники.ФизическоеЛицо.МестоРождения КАК МестоРождения} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ ЗНАЧЕНИЕ(Справочник.Сотрудники.ПустаяСсылка) КАК Сотрудник, "" КАК ТабельныйНомер, ЗНАЧЕНИЕ(Справочник.Организации.ПустаяСсылка) КАК ГоловнаяОрганизация, ЗНАЧЕНИЕ(Справочник.Организации.ПустаяСсылка) КАК Организация, ЗНАЧЕНИЕ(Справочник.ПодразделенияОрганизаций.ПустаяСсылка) КАК Подразделение, ЗНАЧЕНИЕ(Справочник.Должности.ПустаяСсылка) КАК Должность, ЗНАЧЕНИЕ(Перечисление.ВидыЗанятости.ПустаяСсылка) КАК ВидЗанятости, ДАТАВРЕМЯ(1, 1, 1) КАК ДатаПриема, ДАТАВРЕМЯ(1, 1, 1) КАК ДатаУвольнения, ЗНАЧЕНИЕ(Справочник.ОснованияУвольнения.ПустаяСсылка) КАК ПриказОбУвольненииСтатьяТКРФ, "" КАК ПриказОбУвольненииНомер, ДАТАВРЕМЯ(1, 1, 1) КАК ПриказОбУвольненииДата, ЗНАЧЕНИЕ(Справочник.ФизическиеЛица.ПустаяСсылка) КАК ФизическоеЛицо, ВЫРАЗИТЬ("" КАК СТРОКА) КАК Фамилия, ВЫРАЗИТЬ("" КАК СТРОКА) КАК Имя, ВЫРАЗИТЬ("" КАК СТРОКА) КАК Отчество, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ФИОПолные, ДАТАВРЕМЯ(1, 1, 1) КАК ДатаРождения, ЗНАЧЕНИЕ(Перечисление.ПолФизическогоЛица.ПустаяСсылка) КАК Пол, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ИНН, ВЫРАЗИТЬ("" КАК СТРОКА) КАК СтраховойНомерПФР, ВЫРАЗИТЬ("" КАК СТРОКА) КАК МестоРождения, ЗНАЧЕНИЕ(Справочник.СтраныМира.ПустаяСсылка) КАК Страна, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ДокументСерия, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ДокументНомер, ДАТАВРЕМЯ(1, 1, 1) КАК ДокументДатаВыдачи, ДАТАВРЕМЯ(1, 1, 1) КАК ДокументСрокДействия, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ДокументКемВыдан, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ДокументКодПодразделения, ЗНАЧЕНИЕ(Справочник.ВидыДокументовФизическихЛиц.ПустаяСсылка) КАК ДокументВид, ДАТАВРЕМЯ(1, 1, 1) КАК ДатаРегистрации, "" КАК АдресПоПрописке, ВЫРАЗИТЬ("" КАК СТРОКА) КАК АдресПоПропискеПредставление, "" КАК АдресМестаПроживания, ВЫРАЗИТЬ("" КАК СТРОКА) КАК АдресМестаПроживанияПредставление, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ТелефонДомашнийПредставление, ВЫРАЗИТЬ("" КАК СТРОКА) КАК ТелефонРабочийПредставление ПОМЕСТИТЬ Представления_КадровыеДанныеСотрудников ИЗ ВТСотрудники КАК ВТСотрудники ГДЕ "ТолькоРазрешенные" = ИСТИНА ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ Представления_КадровыеДанныеСотрудников.Сотрудник КАК Сотрудник, Представления_КадровыеДанныеСотрудников.ТабельныйНомер КАК ТабельныйНомер, Представления_КадровыеДанныеСотрудников.ГоловнаяОрганизация КАК ГоловнаяОрганизация, Представления_КадровыеДанныеСотрудников.Организация КАК Организация, Представления_КадровыеДанныеСотрудников.Подразделение КАК Подразделение, Представления_КадровыеДанныеСотрудников.Должность КАК Должность, Представления_КадровыеДанныеСотрудников.ВидЗанятости КАК ВидЗанятости, Представления_КадровыеДанныеСотрудников.ДатаПриема КАК ДатаПриема, ВЫБОР КОГДА Представления_КадровыеДанныеСотрудников.ДатаУвольнения <= &Период ТОГДА Представления_КадровыеДанныеСотрудников.ДатаУвольнения ИНАЧЕ ДАТАВРЕМЯ(1, 1, 1) КОНЕЦ КАК ДатаУвольнения, ВЫБОР КОГДА Представления_КадровыеДанныеСотрудников.ДатаУвольнения <= &Период ТОГДА Представления_КадровыеДанныеСотрудников.ПриказОбУвольненииСтатьяТКРФ ИНАЧЕ ЗНАЧЕНИЕ(Справочник.ОснованияУвольнения.ПустаяСсылка) КОНЕЦ КАК ПриказОбУвольненииСтатьяТКРФ, ВЫБОР КОГДА Представления_КадровыеДанныеСотрудников.ДатаУвольнения <= &Период ТОГДА Представления_КадровыеДанныеСотрудников.ПриказОбУвольненииНомер ИНАЧЕ "" КОНЕЦ КАК ПриказОбУвольненииНомер, ВЫБОР КОГДА Представления_КадровыеДанныеСотрудников.ДатаУвольнения <= &Период ТОГДА Представления_КадровыеДанныеСотрудников.ПриказОбУвольненииДата ИНАЧЕ ДАТАВРЕМЯ(1, 1, 1) КОНЕЦ КАК ПриказОбУвольненииДата, Представления_КадровыеДанныеСотрудников.ФизическоеЛицо КАК ФизическоеЛицо, Представления_КадровыеДанныеСотрудников.ИНН КАК ИНН, ДокументыИР.ВидДокумента КАК ВидДокумента, ДокументыИР.Серия КАК Серия, ДокументыИР.Номер КАК Номер, ДокументыИР.ДатаВыдачи КАК ДатаВыдачи, ДокументыИР.СрокДействия КАК СрокДействия, ДокументыИР.ГосударственныйОрган КАК ГосударственныйОрган, ДокументыИР.ДопПоле КАК ДопПолеЗначение, ДокументыИР.ВидДокумента.ИспользоватьДопПоле КАК ДопПолеИспользовать, ДокументыИР.ВидДокумента.НазваниеДопПоля КАК ДопПолеНазвание, ДокументыИР.Архив КАК Архив, ВЫБОР КОГДА ДокументыИР.Архив = ИСТИНА ТОГДА "Архивный" КОГДА ДокументыИР.СрокДействия = ДАТАВРЕМЯ(1, 1, 1) ТОГДА "Бессрочный" КОГДА ДокументыИР.СрокДействия < КОНЕЦПЕРИОДА(&Период, ДЕНЬ) ТОГДА "Просроченный" КОГДА ДОБАВИТЬКДАТЕ(ДокументыИР.СрокДействия, ДЕНЬ, -ДокументыИР.ВидДокумента.СрокНапоминания) < КОНЕЦПЕРИОДА(&Период, ДЕНЬ) ТОГДА "Заканчивается срок действия" ИНАЧЕ "Актуальный" КОНЕЦ КАК АктуальностьДокумента, ВЫБОР КОГДА ДокументыИР.СрокДействия = ДАТАВРЕМЯ(1, 1, 1) ТОГДА NULL ИНАЧЕ РАЗНОСТЬДАТ(КОНЕЦПЕРИОДА(&Период, ДЕНЬ), ДокументыИР.СрокДействия, ДЕНЬ) КОНЕЦ КАК ОсталосьДоОкончанияСрокаДействия {ВЫБРАТЬ Сотрудник.*, ТабельныйНомер, ФизическоеЛицо.*, ГоловнаяОрганизация.*, Организация.*, ВидЗанятости, Подразделение.*, Должность.*, ДатаПриема, ДатаУвольнения, ИНН, ВидДокумента.*, Серия, Номер, ДатаВыдачи, СрокДействия, ГосударственныйОрган.*, ДопПолеЗначение, ДопПолеИспользовать, ДопПолеНазвание, Архив, АктуальностьДокумента, ОсталосьДоОкончанияСрокаДействия} ИЗ Представления_КадровыеДанныеСотрудников КАК Представления_КадровыеДанныеСотрудников ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.бит_ум_ДокументыИР.СрезПоследних(&Период, ) КАК ДокументыИР ПО Представления_КадровыеДанныеСотрудников.ФизическоеЛицо = ДокументыИР.Физлицо {ГДЕ Представления_КадровыеДанныеСотрудников.Сотрудник.*, Представления_КадровыеДанныеСотрудников.ТабельныйНомер, Представления_КадровыеДанныеСотрудников.ФизическоеЛицо.*, Представления_КадровыеДанныеСотрудников.ГоловнаяОрганизация.*, Представления_КадровыеДанныеСотрудников.ВидЗанятости.* КАК ВидЗанятости, Представления_КадровыеДанныеСотрудников.Организация.*, Представления_КадровыеДанныеСотрудников.Подразделение.*, Представления_КадровыеДанныеСотрудников.Должность.*, Представления_КадровыеДанныеСотрудников.ДатаПриема, Представления_КадровыеДанныеСотрудников.ДатаУвольнения, Представления_КадровыеДанныеСотрудников.ДатаРождения, Представления_КадровыеДанныеСотрудников.ИНН, ДокументыИР.ВидДокумента.*, ДокументыИР.Серия, ДокументыИР.Номер, ДокументыИР.ДатаВыдачи, ДокументыИР.СрокДействия, ДокументыИР.ГосударственныйОрган.*, ДокументыИР.ДопПоле, ДокументыИР.Архив, ДокументыИР.ВидДокумента.ИспользоватьДопПоле, ДокументыИР.ВидДокумента.НазваниеДопПоля, (ВЫБОР КОГДА ДокументыИР.Архив = ИСТИНА ТОГДА "Архивный" КОГДА ДокументыИР.СрокДействия = ДАТАВРЕМЯ(1, 1, 1) ТОГДА "Бессрочный" КОГДА ДокументыИР.СрокДействия < КОНЕЦПЕРИОДА(&Период, ДЕНЬ) ТОГДА "Просроченный" КОГДА ДОБАВИТЬКДАТЕ(ДокументыИР.СрокДействия, ДЕНЬ, -ДокументыИР.ВидДокумента.СрокНапоминания) < КОНЕЦПЕРИОДА(&Период, ДЕНЬ) ТОГДА "Заканчивается срок действия" ИНАЧЕ "Актуальный" КОНЕЦ) КАК АктуальностьДокумента, (ВЫБОР КОГДА ДокументыИР.СрокДействия = ДАТАВРЕМЯ(1, 1, 1) ТОГДА NULL ИНАЧЕ РАЗНОСТЬДАТ(КОНЕЦПЕРИОДА(&Период, ДЕНЬ), ДокументыИР.СрокДействия, ДЕНЬ) КОНЕЦ) КАК ОсталосьДоОкончанияСрокаДействия}
